use hec_native_ic::{counted,fp::Fp,poly::Poly,jac::{Curve,Div},instance::factor_base,oracle::{split,OracleStats,Roots}};
use std::collections::BTreeMap;
#[derive(Clone)]struct Case{a:Div,t:u64,x1:u64,x2:u64}
fn old(c:&Curve,a:&Div,t:u64,x1:u64,x2:u64)->Poly{let f=&c.fp;let w=a.v.add(&a.u.scale(t,f),f);let h=c.f.sub(&w.mul(&w,f),f).div_exact(&a.u,f);h.div_exact(&Poly::x_minus(x1,f).mul(&Poly::x_minus(x2,f),f),f)}
fn fast(c:&Curve,a:&Div,t:u64,x1:u64,x2:u64)->Poly{let f=&c.fp;let g=c.g;let mut h=[0;4];h[0]=1;let mut ww=[0;3];ww[0]=t;for j in 1..g-1{ww[j]=f.add(f.mul(t,a.u.c[g-j]),a.v.c[g-j]);}for k in 1..g{let mut v=0;for j in 0..k{v=f.add(v,f.mul(ww[j],ww[k-1-j]));}for j in 1..=k{v=f.add(v,f.mul(a.u.c[g-j],h[k-j]));}h[k]=f.neg(v);}let s=f.add(x1,x2);let r=f.mul(x1,x2);let mut q=[0;4];q[0]=1;for j in 1..g{q[j]=f.add(h[j],f.mul(s,q[j-1]));if j>=2{q[j]=f.sub(q[j],f.mul(r,q[j-2]));}}let mut coeff=vec![0;g];for j in 0..g{coeff[g-1-j]=q[j];}Poly::from_coeffs(&coeff)}
fn brute(q:&Poly,f:&Fp)->Option<Vec<(u64,u32)>>{let mut rem=*q;let mut out=vec![];for x in 0..f.p{let factor=Poly::x_minus(x,f);let mut m=0;while rem.deg()>0&&rem.eval(x,f)==0{rem=rem.div_exact(&factor,f);m+=1;}if m>0{out.push((x,m));}}if rem==Poly::one(){Some(out)}else{None}}
fn main(){counted::disable();println!("g\tp\trep\tarm\tcases\tmodulus\tcounts");let mut total=0;for(g,p,cc)in[(2,101,2),(3,113,3),(4,109,1)]{let mut fc=vec![0;2*g+2];fc[0]=cc;fc[2*g+1]=1;let c=Curve::new(Fp::new(p),Poly::from_coeffs(&fc));assert_eq!(Poly::gcd(&c.f,&c.f.deriv(&c.fp),&c.fp),Poly::one());let f=&c.fp;let fb=factor_base(&c);let &(bx,by)=fb.iter().find(|p|p.0!=0).unwrap();let base=c.place(bx,by);let mut anchor=c.zero();let mut cases=vec![];let(mut anchors,mut excluded)=(0,0);for _ in 0..32{anchor=c.add(&anchor,&base);assert!(c.is_valid(&anchor));if anchor.u.deg()!=g as isize{continue}anchors+=1;let mut buckets=BTreeMap::<u64,Vec<(u64,u64)>>::new();for &(x,y)in &fb{let u=anchor.u.eval(x,f);if u==0{excluded+=1;continue}let iv=f.inv(u);let v=anchor.v.eval(x,f);for yy in if y==0{vec![y]}else{vec![y,f.neg(y)]}{let t=f.mul(f.sub(yy,v),iv);buckets.entry(t).or_default().push((x,yy));}}for(t,pts)in buckets{let a=pts[0];if let Some(b)=pts.iter().find(|b|b.0!=a.0){cases.push(Case{a:anchor,t,x1:a.0,x2:b.0});}}}
 let(mut splitn,mut nonsplit,mut repeats,mut overlaps)=(0,0,0,0);for z in &cases{let q=old(&c,&z.a,z.t,z.x1,z.x2);assert_eq!(q,fast(&c,&z.a,z.t,z.x1,z.x2));let w=z.a.v.add(&z.a.u.scale(z.t,f),f);let pair=Poly::x_minus(z.x1,f).mul(&Poly::x_minus(z.x2,f),f);assert_eq!(z.a.u.mul(&pair,f).mul(&q,f),c.f.sub(&w.mul(&w,f),f));let expected=brute(&q,f);let roots=split(&q,f,&mut OracleStats::default());assert_eq!(roots.map(|x|x.as_slice().to_vec()),expected);if let Some(roots)=roots{splitn+=1;let mut group=c.add_place(&z.a,z.x1,w.eval(z.x1,f));group=c.add_place(&group,z.x2,w.eval(z.x2,f));for &(x,m)in roots.as_slice(){if m>1{repeats+=1;}if x==z.x1||x==z.x2{overlaps+=1;}for _ in 0..m{group=c.add_place(&group,x,w.eval(x,f));}}assert!(c.is_zero(&group));}else{nonsplit+=1;}}
 assert!(!cases.is_empty());if g>=3{assert!(splitn>0&&nonsplit>0);}let mut first=None;for rep in 0..2{let mut signature=vec![];let mut outputs:Option<Vec<(Poly,Option<Roots>)>>=None;for arm in 0..2{counted::reset();let out:Vec<_>=cases.iter().map(|z|{let q=if arm==0{old(&c,&z.a,z.t,z.x1,z.x2)}else{fast(&c,&z.a,z.t,z.x1,z.x2)};let roots=split(&q,f,&mut OracleStats::default());(q,roots)}).collect();let counts=counted::snapshot();counted::disable();if let Some(ref prev)=outputs{assert_eq!(prev,&out)}else{outputs=Some(out)}for(m,v)in &counts{assert_eq!(*m,p);assert_eq!(v[8],2*v[7]+v[5]+v[6]);println!("{g}\t{p}\t{rep}\t{arm}\t{}\t{m}\t{}",cases.len(),v.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}signature.push(counts);}if let Some(ref prev)=first{assert_eq!(prev,&signature)}else{first=Some(signature)}}total+=cases.len();eprintln!("g={g} p={p} anchors={anchors} cases={} split={splitn} nonsplit={nonsplit} residual_multiple_roots={repeats} residual_overlap_known={overlaps} excluded_u_zero_places={excluded}",cases.len());}eprintln!("PASS genera=2,3,4 cases={total} exact_polynomial_identity=true brute_split_agreement=true split_native_group_checks=true repeated_cost_vectors=true component_only=true independent_verification=false");}
